function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('toast').hidden=true,6500);}
function ask(s){return new Promise(resolve=>{const dialog=$('confirmDialog');if(dialog.open)return resolve(false);$('confirmText').textContent=s;const done=value=>{dialog.close();resolve(value);};$('confirmNo').onclick=()=>done(false);$('confirmYes').onclick=()=>done(true);dialog.oncancel=e=>{e.preventDefault();done(false);};dialog.showModal();});}
function transact(mode,action){return new Promise((resolve,reject)=>{const tx=db.transaction('data',mode),req=action(tx.objectStore('data'));tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
async function save(){if(!db)throw Error('Lokaler Speicher ist nicht verfügbar.');await transact('readwrite',s=>s.put(game,'game'));}
