 $('resumeAdventure').hidden=!(state.active||state.done||state.ready);$('resumeLabel').firstChild.textContent=state.action;$('resumeDetail').textContent=state.detail;$('chapter-houses').classList.toggle('recommended',state.first);$('chapter-hunt').classList.toggle('chapter-current',state.active);
