function openAdventure(){if(game.routeId==='hogwarts'&&(!HOUSES.every(h=>game.stations.some(s=>s.house===h.name))||game.stations.filter(s=>s.kind==='finale').length!==1||game.stations.at(-1)?.kind!=='finale'))return toast('Die Route braucht alle vier Hausviertel und genau ein Finale am Schluss. Bitte in der Spielleitung ergänzen.');if(game.routeId!=='hogwarts')return toast('Die Hogwarts-Route kann in der Spielleitung geladen werden. Eure Teststationen bleiben bis dahin erhalten.');navigate(!game.progress.started?'prologue':game.progress.pending?'success':game.progress.vault?'vault':game.progress.arrived?'riddle':'clue');}
