// Geographic map and foreground-only location watch.
function applyMap(){const {x,y,w,h}=mapBox;$('mapSvg').setAttribute('viewBox',`${x} ${y} ${w} ${h}`);}
function zoom(factor,anchor={x:mapBox.x+mapBox.w/2,y:mapBox.y+mapBox.h/2}){const w=Math.min(1400,Math.max(180,mapBox.w*factor)),h=w*849/1000;const ratio=w/mapBox.w;mapBox={x:anchor.x-(anchor.x-mapBox.x)*ratio,y:anchor.y-(anchor.y-mapBox.y)*ratio,w,h};clampMap();applyMap();}
function clampMap(){mapBox.x=Math.min(1000-mapBox.w*.2,Math.max(-mapBox.w*.8,mapBox.x));mapBox.y=Math.min(849-mapBox.h*.2,Math.max(-mapBox.h*.8,mapBox.y));}
function svgPoint(event){const p=$('mapSvg').createSVGPoint();p.x=event.clientX;p.y=event.clientY;return p.matrixTransform($('mapSvg').getScreenCTM().inverse());}
$('zoomIn').onclick=()=>zoom(.75);$('zoomOut').onclick=()=>zoom(1.33);$('centerMap').onclick=()=>{if(lastFix&&inMap(lastFix)){const p=project(lastFix);mapBox.x=p.x-mapBox.w/2;mapBox.y=p.y-mapBox.h/2;}else mapBox={x:0,y:0,w:1000,h:849};applyMap();};
$('mapSvg').onpointerdown=e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});$('mapSvg').setPointerCapture(e.pointerId);if(pointers.size===1)drag={clientX:e.clientX,clientY:e.clientY,box:{...mapBox}};if(pointers.size===2){const [a,b]=[...pointers.values()];pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),width:mapBox.w};drag=null;}};
$('mapSvg').onpointermove=e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2&&pinch){const [a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(d>1)zoom((pinch.width*pinch.distance/d)/mapBox.w);return;}if(drag&&pointers.size===1){const rect=$('mapSvg').getBoundingClientRect(),scale=Math.max(mapBox.w/rect.width,mapBox.h/rect.height);mapBox.x=drag.box.x-(e.clientX-drag.clientX)*scale;mapBox.y=drag.box.y-(e.clientY-drag.clientY)*scale;clampMap();applyMap();}};
for(const event of ['pointerup','pointercancel','lostpointercapture'])$('mapSvg').addEventListener(event,e=>{pointers.delete(e.pointerId);drag=null;pinch=null;});
