function renderMarkers(){const root=$('stationMarkers');root.replaceChildren();game.stations.forEach((s,i)=>{if(!s.point||!markerVisible(i,game.progress))return;const p=project(s.point),g=document.createElementNS(NS,'g');g.setAttribute('transform',`translate(${p.x},${p.y})`);const mark=document.createElementNS(NS,'path');mark.setAttribute('d','M0 -18 12 0 0 18 -12 0Z');mark.setAttribute('fill',i<game.progress.step?'#6b6341':'#963e2e');mark.setAttribute('stroke','#fff1d4');mark.setAttribute('stroke-width','3');g.append(mark);root.append(g);});}
function paintPosition(p){const marker=$('userMarker');if(inMap(p))marker.removeAttribute('hidden');else marker.setAttribute('hidden','');marker.setAttribute('visibility',inMap(p)?'visible':'hidden');if(!inMap(p))return;const q=project(p);marker.setAttribute('transform',`translate(${q.x},${q.y})`);const metersPerUnit=(MAP.east-MAP.west)*111195*Math.cos((MAP.north+MAP.south)/2*Math.PI/180)/1000;$('accuracyCircle').setAttribute('r',Math.min(1500,p.accuracy/metersPerUnit));}
