 $('startSearch').textContent='Spur aufnehmen';$('nearHint').textContent=s.hint;if(game.progress.arrived){$('nearTitle').textContent='Ort gefunden';$('nearDistance').textContent='Euer Rätsel wartet auf euch';$('gpsDetail').textContent='';$('locationState').textContent='Fundort bestätigt';return;}
