$('showHint').onclick=()=>{const s=game.stations[game.progress.step];if(!s)return;toast(s.hint);if(s.photo){$('riddlePhoto').src=s.photo;$('riddlePhoto').alt='Foto-Hinweis';$('riddleTitle').textContent=game.progress.arrived?s.title:'Die nächste Spur';$('riddleQuestion').textContent=s.hint;$('answerForm').hidden=true;$('riddleRunes').hidden=true;$('riddlePhoto').hidden=false;navigate('riddle');}};
