function renderRiddle(){const current=game.stations[game.progress.step];if(!current)return navigate('vault');if(game.progress.pending)return navigate('success');const reached=game.progress.arrived;$('riddleTitle').textContent=reached?current.title:'Die nächste Spur';const art=({coins:'creature',domino:'scroll',memory:'castle',bus:'knight-bus',finale:'tree'})[current.kind]||'tree';$('riddlePhoto').hidden=!reached&&!current.photo;$('riddlePhoto').src=!reached&&current.photo?current.photo:`assets/${art}.jpg`;$('riddlePhoto').alt=reached?current.title:'Foto-Hinweis zum gesuchten Ort';$('riddleStory').textContent=reached?current.story:'';$('riddleStory').hidden=!reached;$('riddleQuestion').textContent=reached?current.question:current.hint;$('answerForm').hidden=!reached;$('riddleRunes').hidden=!reached;document.querySelector('.found').hidden=!reached;$('answer').value='';$('puzzleContent').replaceChildren();$('riddleHelp').hidden=!reached||!current.hints.length;$('hintText').textContent='';if(reached)renderPuzzle(current);makeRunes($('riddleRunes'));}
