$('answerForm').onsubmit=async e=>{e.preventDefault();const current=game.stations[game.progress.step];if(!current||!game.progress.arrived||locked||game.progress.pending)return;if(normalize($('answer').value)!==normalize(current.answer))return toast('Diese Lösung stimmt noch nicht. Beratet euch oder öffnet einen Hinweis.');if(await mutate(()=>{if(!completeStation(game,$('answer').value))throw Error('Für das Finale braucht ihr alle vier Hausviertel.');})){navigate('success');toast(current.house?`${current.house} gefunden!`:'Hogwarts ist wieder vereint!');}};
// Preparation: edit one station at a time, never publish local locations/photos.
function updateEditStatus(saved=false){$('editStatus').textContent=saved?'✓ Änderungen gespeichert. Ihr könnt diese Station jederzeit erneut bearbeiten.':dirty?'● Ungespeicherte Änderungen':'Gespeicherte Station geladen. Texte, Foto und Fundort können geändert werden.';$('editStatus').classList.toggle('unsaved',dirty);$('discardStation').disabled=!dirty;}
function fillEditor(){updateEditStatus();const s=draft;for(const [id,key] of [['editTitle','title'],['editHint','hint'],['editQuestion','question'],['editAnswer','answer'],['editRadius','radius'],['editStory','story'],['editSuccess','success']])$(id).value=s[key];$('editHouse').value=s.house||'';$('editKind').value=s.kind;$('editHints').value=s.hints.join('\n');$('pointStatus').textContent=s.point?`✓ Fundort gespeichert${inMap(s.point)?'':' · außerhalb des Kartenausschnitts'}`:'Noch kein GPS-Fundort gespeichert';$('photoPreview').hidden=!s.photo;$('removePhoto').hidden=!s.photo;if(s.photo)$('photoPreview').src=s.photo;$('photoStatus').textContent=s.photo?'Foto vorhanden':'Noch kein Foto';}
function buildEditor(){draft=structuredClone(game.stations[editIndex]);dirty=false;const sel=$('editStation');sel.replaceChildren();game.stations.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=`${i+1}. ${s.title}`;sel.append(o);});sel.value=editIndex;fillEditor();$('deleteStation').disabled=game.stations.length<=1;}
$('stationForm').oninput=()=>{dirty=true;updateEditStatus();};$('discardStation').onclick=async()=>{if(!dirty||await ask('Alle ungespeicherten Änderungen an dieser Station verwerfen?'))buildEditor();};$('editStation').onchange=async()=>{if(dirty&&!await ask('Ungespeicherte Änderungen verwerfen?')){$('editStation').value=editIndex;return;}editIndex=Number($('editStation').value);buildEditor();};
function collectDraft(){return{...draft,title:$('editTitle').value,hint:$('editHint').value,question:$('editQuestion').value,answer:$('editAnswer').value,radius:Number($('editRadius').value),story:$('editStory').value,success:$('editSuccess').value,house:$('editHouse').value||null,kind:$('editKind').value,hints:$('editHints').value.split('\n').map(x=>x.trim()).filter(Boolean)};}
function positionNow(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(Error('Standort nicht unterstützt.'));navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lon:p.coords.longitude,accuracy:p.coords.accuracy}),e=>reject(Error(e.code===1?'Standortzugriff verweigert.':'Standort nicht verfügbar. Bitte draußen erneut versuchen.')),{enableHighAccuracy:true,maximumAge:0,timeout:20000});});}
$('capturePoint').onclick=async()=>{if(photoBusy)return;photoBusy=true;$('capturePoint').disabled=true;try{const p=await positionNow();if(p.accuracy>100)throw Error('Standort noch zu ungenau. Bitte draußen erneut versuchen.');draft=collectDraft();draft.point={lat:p.lat,lon:p.lon};dirty=true;fillEditor();$('pointStatus').textContent=`✓ Erfasst, ±${Math.round(p.accuracy)} m. Bitte Station speichern.${inMap(p)?'':' Fundort liegt außerhalb der Karte.'}`;}catch(e){toast(e.message);}finally{photoBusy=false;$('capturePoint').disabled=false;}};
$('photoInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;photoBusy=true;$('saveStation').disabled=true;try{if(file.size>25*1024*1024)throw Error('Bitte ein Foto unter 25 MB wählen.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,1200/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);draft=collectDraft();draft.photo=canvas.toDataURL('image/jpeg',.8);dirty=true;fillEditor();toast('Foto vorbereitet. Bitte Station speichern.');}finally{URL.revokeObjectURL(url);}}catch(e){toast(e.message||'Foto nicht lesbar. Bitte JPEG/PNG verwenden.');}finally{photoBusy=false;$('saveStation').disabled=false;e.target.value='';}};
$('removePhoto').onclick=()=>{draft=collectDraft();draft.photo=null;dirty=true;fillEditor();};
$('stationForm').onsubmit=async e=>{e.preventDefault();if(photoBusy||locked)return;let next;try{next=validateStations([collectDraft()])[0];}catch(e){return toast(e.message);}if(JSON.stringify(next)===JSON.stringify(game.stations[editIndex])){dirty=false;updateEditStatus(true);toast('Die Station ist bereits auf dem aktuellen Stand gespeichert.');return;}if((game.progress.step||game.progress.arrived||game.progress.pending||game.progress.vault)&&!await ask('Route ändern und den Schnitzeljagd-Fortschritt zurücksetzen? Hauszuordnungen bleiben erhalten. Automatisch vergebene Rätselpunkte werden zurückgesetzt.'))return;if(await mutate(()=>{game.stations[editIndex]=next;if(next.kind==='finale')game.code=next.answer;resetRouteProgress();})){buildEditor();updateEditStatus(true);toast('Änderungen an der Station gespeichert.');}};
$('addStation').onclick=async()=>{if(photoBusy||locked)return;if(game.stations.length>=12)return toast('Maximal zwölf Stationen.');if(dirty&&!await ask('Ungespeicherte Änderungen verwerfen?'))return;if((game.progress.step||game.progress.arrived||game.progress.pending)&&!await ask('Station hinzufügen und Schnitzeljagd neu starten?'))return;const end=game.stations.findIndex(s=>s.kind==='finale'),index=end<0?game.stations.length:end;if(await mutate(()=>{game.stations.splice(index,0,validateStations([{...defaultStations()[0],id:crypto.randomUUID(),kind:'custom',title:`Zusatzstation ${game.stations.length}`}])[0]);resetRouteProgress();})){editIndex=index;buildEditor();}};
