$('override').onclick=async()=>{if(game.progress.pending)return navigate('success');if(game.progress.step>=game.stations.length)return toast('Alle Orte sind bereits gefunden.');if(!await ask('Spielleitung: Seid ihr am richtigen Ort? Fundort bestätigen?'))return;if(await mutate(()=>{game.progress.started=true;game.progress.arrived=true;})){dirty=false;navigate('riddle');toast('Fundort durch die Spielleitung bestätigt.');}};
