$('saveCode').onclick=async()=>{const value=$('vaultCode').value.trim();if(!value)return toast('Bitte einen Abschlusscode eingeben.');if(value===game.code)return toast('Der Code ist bereits gespeichert.');if(!await ask('Abschlusscode ändern? Der Routenfortschritt wird zurückgesetzt, damit Wappen und Finale konsistent bleiben.'))return;if(await mutate(()=>{game.code=value;const finale=game.stations.find(s=>s.kind==='finale');if(finale)finale.answer=value;resetRouteProgress();}))toast('Abschlusscode gespeichert.');};
function renderHouseAdmin(){const root=$('houseAdmin');root.replaceChildren();game.members.forEach(m=>{const label=addText(root,'label',m.name),select=document.createElement('select');select.setAttribute('aria-label',`Haus für ${m.name}`);houseNames.forEach(h=>{const o=document.createElement('option');o.value=h;o.textContent=h;select.append(o);});select.value=m.house;select.onchange=async()=>{if(!await mutate(()=>game.members.find(p=>p.id===m.id).house=select.value))select.value=game.members.find(p=>p.id===m.id).house;};root.append(select);});if(!game.members.length)addText(root,'p','Noch keine Kinder eingeteilt.','micro');}
