function validateGame(data){const stations=validateStations(data.stations);if(!Array.isArray(data.members)||data.members.length>100||data.members.some(m=>typeof m.name!=='string'||m.name.length>50||!houseNames.includes(m.house)))throw Error('Ungültige Kinder/Häuser.');if(typeof data.code!=='string'||!data.code.trim()||data.code.length>40)throw Error('Ungültiger Abschlusscode.');const progress=validateCampaignProgress(data.progress,stations);if(!Array.isArray(data.points)||data.points.some(p=>!HOUSES.some(h=>h.name===p.house)||!Number.isInteger(p.delta)||Math.abs(p.delta)>1000||typeof p.reason!=='string'||p.reason.length>200)||!Array.isArray(data.pointSources)||data.pointSources.some(id=>!stations.some(s=>s.id===id)))throw Error('Ungültige Hauspunkte.');return{version:5,routeId:data.routeId==='hogwarts'?'hogwarts':'legacy',stations,progress,members:data.members.map(m=>({id:m.id||crypto.randomUUID(),name:m.name,house:m.house})),points:data.points,pointSources:data.pointSources,code:data.code,houseTransfer:data.houseTransfer&&Number.isFinite(Date.parse(data.houseTransfer.exportedAt))&&Number.isFinite(Date.parse(data.houseTransfer.importedAt))?{exportedAt:data.houseTransfer.exportedAt,importedAt:data.houseTransfer.importedAt}:undefined};}
function legacyGame(data){const stations=validateStations(data.stations);if(!validProgress(data.progress,stations.length))throw Error('Alte Sicherung ist ungültig.');return{version:5,routeId:'legacy',stations,progress:campaignProgress(),members:data.members||[],points:[],pointSources:[],code:typeof data.code==='string'?data.code:'3719'};}
$('importGame').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>65*1024*1024)throw Error('Sicherung ist zu groß.');const imported=JSON.parse(await file.text());if(![2,3].includes(imported.schema))throw Error('Unbekanntes Sicherungsformat.');const restored=imported.schema===3?validateGame(imported.game):legacyGame(imported.game);if(!await ask('Gespeicherte Stationen, Fotos, Hauspunkte und Spielstand durch diese Sicherung ersetzen? Die Eltern-PIN bleibt erhalten.'))return;if(await mutate(()=>game=restored)){editIndex=0;buildEditor();renderHouseAdmin();$('vaultCode').value=game.code;toast('Sicherung importiert.');}}catch(e){toast(e.message||'Sicherung konnte nicht gelesen werden.');}finally{e.target.value='';}};
function resetRouteProgress(){game.progress=campaignProgress();game.points=(game.points||[]).filter(p=>!p.source);game.pointSources=[];}
