$('downloadContentArchive').onclick=async()=>{const archived=await transact('readonly',s=>s.get('content-archive-v7'));if(!archived)return toast('Noch kein Klasse-3-Update archiviert.');const url=URL.createObjectURL(new Blob([JSON.stringify({schema:3,game:archived},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='geheime-karte-vor-klasse3.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('loadHogwarts').onclick=async()=>{if(!adminUnlocked||!await ask('Die fünf Hogwarts-Stationen laden? Eure aktuelle Route wird zuvor lokal archiviert. GPS-Fundorte der neuen Route müssen zugeordnet werden.'))return;try{await transact('readwrite',s=>s.put(structuredClone(game),'route-archive'));if(await mutate(()=>{game={version:5,routeId:'hogwarts',stations:campaignStations(),progress:campaignProgress(),members:game.members,points:[],pointSources:[],code:'3719'};})){editIndex=0;buildEditor();$('vaultCode').value=game.code;toast('Hogwarts-Route geladen. Alte Route ist lokal archiviert.');}}catch{toast('Die alte Route konnte nicht gesichert werden. Es wurde nichts ersetzt.');}};
$('downloadArchive').onclick=async()=>{try{const archived=await transact('readonly',s=>s.get('route-archive'));if(!archived)return toast('Noch keine archivierte Route vorhanden.');const url=URL.createObjectURL(new Blob([JSON.stringify({schema:3,game:archived},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='geheime-karte-alte-route.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{toast('Archiv konnte nicht gelesen werden.');}};
function network(){$('network').textContent=navigator.onLine?'◉ Netz verfügbar':'◌ Ohne Netz';}window.addEventListener('online',network);window.addEventListener('offline',network);network();
async function offline(){if(!('serviceWorker'in navigator)){$('offline').textContent='Offline-Modus nicht verfügbar';return;}try{const registration=await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;const check=()=>{(navigator.serviceWorker.controller||registration.active)?.postMessage('CHECK_OFFLINE');};navigator.serviceWorker.addEventListener('controllerchange',check);navigator.serviceWorker.addEventListener('message',e=>{if(e.data==='OFFLINE_READY')$('offline').textContent='✓ Offline bereit';});check();}catch{$('offline').textContent='Offline-Dateien fehlen · Internet prüfen';}}
(async()=>{try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('geheime-karte-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});const previous=await transact('readonly',s=>s.get('game'));if(previous){if(previous.version===5)game=validateGame(previous);else{await transact('readwrite',s=>s.put(previous,'original-v4'));game=legacyGame(previous);await save();}}else await save();navigate('home');}catch(e){locked=true;toast(e.message||'Lokaler Speicher nicht verfügbar.');$('offline').textContent='Speichern nicht verfügbar';return;}offline();})();

async function unlockAdmin(change=false){
 if(pinPending||!db)return false;
 pinPending=true;
 let record;
 try{record=await transact('readonly',s=>s.get('parent-pin'));}catch{pinPending=false;toast('PIN-Speicher nicht verfügbar.');return false;}
 const setting=!record||change;
 const dialog=$('pinDialog');$('pinTitle').textContent=setting?'Eltern-PIN festlegen':'Nur für die Spielleitung';
 $('pinInstructions').textContent=setting?'Wähle eine PIN mit 4 bis 8 Ziffern. Richte sie vor der Übergabe an die Kinder ein.':'Gib deine Eltern-PIN ein, um die Spielleitung zu öffnen.';
 $('pinInput').value='';$('pinRepeat').value='';$('pinRepeatLabel').hidden=!setting;$('pinRepeat').hidden=!setting;$('pinRepeat').required=setting;$('pinError').textContent='';
 $('pinInput').setAttribute('autocomplete',setting?'new-password':'current-password');
 const result=await new Promise(resolve=>{
  let settled=false;const done=ok=>{if(settled)return;settled=true;dialog.close();resolve(ok);};$('pinCancel').onclick=()=>done(false);dialog.oncancel=e=>{e.preventDefault();if(!$('pinSubmit').disabled)done(false);};
  $('pinForm').onsubmit=async e=>{e.preventDefault();const pin=$('pinInput').value;if(!validPin(pin)){$('pinError').textContent='Bitte 4 bis 8 Ziffern eingeben.';return;}if(setting&&pin!==$('pinRepeat').value){$('pinError').textContent='Die beiden PINs stimmen nicht überein.';return;}
  $('pinSubmit').disabled=true;$('pinCancel').disabled=true;
  try{if(setting){const data=await createPin(pin);await transact('readwrite',s=>s.put(data,'parent-pin'));done(true);}else if(await checkPin(pin,record)){done(true);}else{$('pinError').textContent='Diese PIN stimmt nicht.';$('pinInput').value='';$('pinInput').focus();}}
  catch{$('pinError').textContent='PIN konnte nicht geprüft oder gespeichert werden.';}
  finally{$('pinSubmit').disabled=false;$('pinCancel').disabled=false;}
  };
  dialog.showModal();$('pinInput').focus();
 });
 $('pinInput').value='';$('pinRepeat').value='';pinPending=false;adminUnlocked=result;return result;
}
$('changePin').onclick=async()=>{if(!adminUnlocked)return;if(await unlockAdmin(true))toast('Neue Eltern-PIN gespeichert.');};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&['setup','points','gamehost'].includes(view)&&!photoBusy&&!houseFileBusy){adminUnlocked=false;pinResume=true;$(view).hidden=true;}else if(!document.hidden&&pinResume){pinResume=false;unlockAdmin().then(ok=>{if(ok&&['setup','points','gamehost'].includes(view))$(view).hidden=false;else{dirty=false;navigate('home');}});}});

// A separate, limited handover. Full game backups keep their existing workflow.
function transferDate(value){return new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));}
function renderHouseTransferStatus(){const t=game.houseTransfer;$('houseTransferStatus').textContent=t?`Zuletzt übernommen: ${transferDate(t.importedAt)} · Datei vom ${transferDate(t.exportedAt)}`:'Noch kein Häuser-/Punktestand von einem anderen Gerät übernommen.';}
function renderHouseBoard(){const root=$('houseBoardCards'),totals=pointsTotals(game);root.replaceChildren();HOUSES.forEach(h=>{const card=addText(root,'article','','board-house');card.style.setProperty('--house-color',h.color);const img=document.createElement('img');img.src=`assets/house-${h.name.toLowerCase()}.svg`;img.alt='';card.append(img);addText(card,'h2',h.name);addText(card,'strong',String(totals[h.name]),'board-total');addText(card,'span','Hauspunkte','board-caption');const list=addText(card,'ul','','board-members'),members=game.members.filter(m=>m.house===h.name);if(members.length)members.forEach(m=>addText(list,'li',m.name));else addText(list,'li','Noch niemand eingeteilt','micro');});$('houseBoardStatus').textContent=game.houseTransfer?`Dateistand vom ${transferDate(game.houseTransfer.exportedAt)} · Änderungen auf diesem Gerät sind möglich.`:'Euer lokal gespeicherter Stand';}
$('openHouseBoard').onclick=()=>navigate('houseboard');
$('openHouseTransfer').onclick=async()=>{await navigate('setup');if(view==='setup'){settingsTab(true);$('houseTransferSettings').scrollIntoView({block:'start'});}};
function downloadHouses(data,prefix='geheime-karte-haeuser-punkte'){
 const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${prefix}-${data.exportedAt.replace(/[:.]/g,'-')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
$('exportHouses').onclick=()=>{if(!adminUnlocked)return;try{downloadHouses(createHouseTransfer(game));toast('Datei gespeichert. Per AirDrop oder iCloud aufs iPad übertragen und dort importieren.');}catch(e){toast(e.message);}};
$('downloadHouseArchive').onclick=async()=>{if(!adminUnlocked)return;try{const archive=await transact('readonly',s=>s.get('house-transfer-archive-v1'));if(!archive)return toast('Noch kein Häuser-/Punktestand vor einem Import archiviert.');downloadHouses(validateHouseTransfer(archive),'geheime-karte-haeuser-vor-import');}catch(e){toast(e.message||'Archiv konnte nicht gelesen werden.');}};
$('chooseHouseFile').onclick=()=>{if(!adminUnlocked||locked||houseFileBusy)return;houseFileBusy=true;$('importHouses').click();};
$('importHouses').addEventListener('cancel',()=>{houseFileBusy=false;});
function previewHouseTransfer(data){return new Promise(resolve=>{
 const dialog=$('houseImportDialog');if(dialog.open)return resolve(false);const root=$('houseImportPreview');root.replaceChildren();
 const totals=pointsTotals(data);addText(root,'p',`${data.members.length} ${data.members.length===1?'Kind':'Kinder'} · ${data.points.length} ${data.points.length===1?'Punktevergabe':'Punktevergaben'}`);
 HOUSES.forEach(h=>{const group=addText(root,'div','','transfer-preview-house');addText(group,'strong',`${h.name}: ${totals[h.name]} Punkte`);addText(group,'p',data.members.filter(m=>m.house===h.name).map(m=>m.name).join(', ')||'Keine Kinder');});
 const older=game.houseTransfer&&Date.parse(data.exportedAt)<Date.parse(game.houseTransfer.exportedAt);$('houseImportDate').textContent=`Exportiert am ${transferDate(data.exportedAt)}${older?' · Achtung: älter als die zuletzt übernommene Datei!':''}`;
 const done=ok=>{dialog.close();resolve(ok);};$('houseImportCancel').onclick=()=>done(false);$('houseImportConfirm').onclick=()=>done(true);dialog.oncancel=e=>{e.preventDefault();done(false);};dialog.showModal();
});}
$('importHouses').onchange=async e=>{
 const file=e.target.files[0];houseFileBusy=false;if(!file)return;
 try{
  if(file.size>HOUSE_TRANSFER_LIMIT)throw Error('Bitte eine Häuser-/Punktedatei unter 1 MB wählen.');
  const data=validateHouseTransfer(JSON.parse(await file.text()));
  if(!adminUnlocked&&!await unlockAdmin())return;
  if(!await previewHouseTransfer(data))return;
  if(!adminUnlocked&&!await unlockAdmin())return;
  if(locked)return;locked=true;
  try{
   const previous=createHouseTransfer(game),next=applyHouseTransfer(game,data);
   // Archive and replacement succeed or fail together in one IndexedDB transaction.
   await transact('readwrite',store=>{store.put(previous,'house-transfer-archive-v1');return store.put(next,'game');});
   game=next;sortStep=-1;sortAnswers=[];refreshSummaries();renderHouseAdmin();renderHouseTransferStatus();
   toast('Häuser und Punkte übernommen. Der Schnitzeljagd-Stand ist erhalten.');
  }finally{locked=false;}
 }catch(error){toast(error instanceof SyntaxError?'Diese Datei enthält kein gültiges JSON.':error.message||'Datei konnte nicht importiert werden.');}
 finally{e.target.value='';houseFileBusy=false;}
};

let indoorCategory='all',indoorId='fuehlkiste',feelRound=0,indoorPointsReturn=false;
function indoorGame(){return INDOOR_GAMES.find(g=>g.id===indoorId)||INDOOR_GAMES[0];}
function renderIndoorGames(){const filters=$('gameCategories'),list=$('indoorGameList');filters.replaceChildren();list.replaceChildren();[{id:'all',title:'Alle Spiele'},...INDOOR_CATEGORIES].forEach(cat=>{const b=actionButton(filters,cat.title,()=>{indoorCategory=cat.id;renderIndoorGames();},'game-filter');b.setAttribute('aria-pressed',String(cat.id===indoorCategory));});INDOOR_GAMES.filter(g=>indoorCategory==='all'||g.category===indoorCategory).forEach(g=>{const b=actionButton(list,'',()=>{if(indoorId!==g.id)feelRound=0;indoorId=g.id;navigate('gameletter');},'indoor-game-card');addText(b,'span',g.optional?'Zusatzidee':INDOOR_CATEGORIES.find(c=>c.id===g.category).title,'eyebrow');addText(b,'strong',g.title);addText(b,'small',`${g.duration} · Brief & Anleitung`);});}
function gameParagraphs(root,text){for(const part of text.split(/\n\s*\n/))addText(root,'p',part);}
function renderGameLetter(){const g=indoorGame();$('gameLetterTitle').textContent=g.title;$('gameLetterMeta').textContent=`${g.duration}${g.optional?' · Freiwillige Zusatzidee':''}`;$('gameLetterSender').textContent=`Eine Nachricht von ${g.sender}`;const art=$('gameLetterArt');art.replaceChildren();if(g.art.startsWith('indoor:')){const img=addText(art,'div','','indoor-illustration');img.style.backgroundPosition=`${Number(g.art.slice(-1))*50}% center`;}else{const img=document.createElement('img');img.src=`assets/${g.art}`;img.alt='';art.append(img);}$('gameLetterText').replaceChildren();gameParagraphs($('gameLetterText'),g.letter);}
function renderGameHost(){const g=indoorGame(),root=$('gameHostContent');$('gameHostTitle').textContent=g.title;root.replaceChildren();for(const [key,title] of [['materials','Das braucht ihr'],['prep','Vorbereiten'],['steps','So läuft das Spiel'],['check','Lösung und Wertung'],['help','Hilfen'],['app','Unterstützung durch die App']]){addText(root,'h2',title);gameParagraphs(root,g[key]);}if(g.questions){addText(root,'h2','Acht Fragen zum Vorlesen');g.questions.forEach((q,i)=>{const section=addText(root,'section','','host-quiz-question');addText(section,'h3',`${i+1}. ${q.question}`);q.choices.forEach((choice,j)=>addText(section,'p',`${'ABC'[j]}: ${choice}`));const detail=addText(section,'details','');addText(detail,'summary','Antwort anzeigen');addText(detail,'p',`${'ABC'[q.answer]}: ${q.choices[q.answer]}`);});}$('feelRounds').hidden=!g.rounds;$('indoorAwardPoints').hidden=Boolean(g.rounds);if(g.rounds)renderFeelRound();}
function renderFeelRound(){const g=indoorGame(),r=g.rounds[feelRound];$('feelRoundTitle').textContent=`Fundstück ${feelRound+1} von ${g.rounds.length}`;$('feelObject').textContent=`Verdeckt einlegen: ${r.object}`;$('feelHint').textContent=r.hint;$('feelSolution').textContent=`Gegenstand: ${r.object} · Geschöpf: ${r.creature}`;$('feelSolution').parentElement.open=false;$('feelPrevious').disabled=feelRound===0;$('feelNext').disabled=feelRound===g.rounds.length-1;}
$('feelPrevious').onclick=()=>{if(feelRound>0){feelRound--;renderFeelRound();}};$('feelNext').onclick=()=>{if(feelRound<indoorGame().rounds.length-1){feelRound++;renderFeelRound();}};
$('openGameHost').onclick=()=>navigate('gamehost');$('readGameLetter').onclick=()=>navigate('gameletter');$('backToGames').onclick=()=>navigate('games');
async function awardIndoor(delta,reason){pointsContext=null;await navigate('points');if(view==='points'){indoorPointsReturn=true;$('pointsAmount').value=delta;$('pointsReason').value=reason;}}
$('feelObjectPoints').onclick=()=>awardIndoor(10,`Hagrids Fühlkiste · Runde ${feelRound+1} · Gegenstand`);$('feelCreaturePoints').onclick=()=>awardIndoor(5,`Hagrids Fühlkiste · Runde ${feelRound+1} · Geschöpf`);$('indoorAwardPoints').onclick=()=>awardIndoor(10,indoorGame().title);
